package com.scanborn.ai.spaces

import java.io.File

/** Only files generated by the viewer cache are eligible; never walk directories. */
internal object AssetRetention {
    private val name = Regex("[0-9a-f-]{36}\\.(bin|ply|obj)")
    fun assets(root: File): List<File> = root.listFiles().orEmpty().filter {
        it.isFile && name.matches(it.name) && it.canonicalFile.parentFile == root.canonicalFile
    }
    fun prune(root: File, keep: Set<String>) {
        assets(root).filter { it.name !in keep }.forEach { it.delete() }
    }
    fun requireSpace(root: File, reserve: Long, maximum: Long = 128L * 1024 * 1024) {
        check(assets(root).sumOf { it.length() } + reserve <= maximum) {
            "Viewer cache limit reached. Let the current scene finish loading before opening another."
        }
    }
}
